import React, { useState } from 'react';
const ItineraryModule = () => {
    const tours = [
        {
          id: 1,
          destination: "Nha Trang | Tàu Đáy Kính Ngắm San Hô | Con Sẻ Tre",
          image: "/images/nha-trang.jpg",
          departureFrom: "Hồ Chí Minh",
          duration: "3 ngày 3 đêm",
          originalPrice: "2,580,000 đ",
          salePrice: "2,380,000 đ",
          tourType: "Tour khách lẻ"
        },
        {
          id: 2,
          destination: "Đà Lạt | Vùng Đất Cổ Tích Fairytale Land",
          image: "/images/dalat-fairytale.jpg",
          departureFrom: "Hồ Chí Minh",
          duration: "4 ngày 3 đêm",
          originalPrice: "3,115,000 đ",
          salePrice: "2,915,000 đ",
          tourType: "Tour khách lẻ"
        },
        // Add the remaining 4 tours...
      ];
    
      return (
        <div className="container mx-auto p-4">
          <h1 className="text-2xl font-bold mb-6">Tour Packages</h1>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {tours.map(tour => (
              <TourCard key={tour.id} tour={tour} />
            ))}
          </div>
        </div>
      );
    };
    
    const TourCard = ({ tour }) => {
      return (
        <div className="border rounded-lg overflow-hidden shadow-md">
          <div className="relative">
            <img 
              src={tour.image} 
              alt={tour.destination} 
              className="w-full h-48 object-cover"
            />
            <div className="absolute bottom-0 left-0 bg-yellow-500 text-white px-4 py-1 rounded-tr-md">
              Đặt Thấy Là
            </div>
          </div>
          
          <div className="p-4">
            <h2 className="text-blue-700 font-semibold text-lg mb-2">{tour.destination}</h2>
            
            <div className="flex items-center text-sm text-gray-600 mb-1">
              <span className="mr-2">🚌</span>
              <span>Xuất phát từ {tour.departureFrom}</span>
            </div>
            
            <div className="flex items-center text-sm text-gray-600 mb-1">
              <span className="mr-2">🕒</span>
              <span>{tour.duration}</span>
            </div>
            
            <div className="flex items-center text-sm text-gray-600 mb-3">
              <span className="mr-2">👥</span>
              <span>{tour.tourType}</span>
            </div>
            
            <div className="flex justify-between items-center">
              <div>
                <div className="text-gray-500 line-through text-sm">{tour.originalPrice}</div>
                <div className="text-red-600 font-bold">{tour.salePrice}</div>
              </div>
              <button className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
                Đặt tour
              </button>
            </div>
          </div>
        </div>
      );
    };
export default ItineraryModule;
